import UIKit

public struct CalmpalArtworkData {
  private static let base64Png = ""

  public static let sharedImage: UIImage = {
    if let data = Data(base64Encoded: base64Png), let img = UIImage(data: data) {
      return img
    }
    if let img = UIImage(named: "NowPlayingLogo") ?? UIImage(named: "AppLogo") {
      return img
    }
    return UIImage()
  }()
}
